// Twilio manda el mensaje como application/x-www-form-urlencoded,
// así que n8n lo deja en $json.body.
const entrada = $input.first().json;
const cuerpo = entrada.body || entrada;

// Lectura tolerante de variables de entorno: si la instancia tiene el acceso
// bloqueado (N8N_BLOCK_ENV_ACCESS_IN_NODE=true), el flujo sigue con el default
// en vez de cortarse.
function leerEnv(clave, porDefecto) {
  try {
    return $env[clave] || porDefecto;
  } catch (error) {
    return porDefecto;
  }
}

const telefonoCrudo = String(cuerpo.From || '').trim();
if (!telefonoCrudo) {
  throw new Error('El webhook no recibió el campo "From" de Twilio. ¿Está bien configurada la URL del sandbox?');
}

// Twilio lo manda como "whatsapp:+549351...". El nodo Twilio de salida vuelve
// a agregar ese prefijo, así que internamente trabajamos con E.164 puro.
const telefonoCliente = telefonoCrudo.replace(/^whatsapp:/i, '');
const mensaje = String(cuerpo.Body || '').trim();

return [
  {
    json: {
      telefonoCliente,
      nombreCliente: String(cuerpo.ProfileName || '').trim() || 'Sin nombre',
      mensaje,
      mensajeVacio: mensaje.length === 0,
      messageSid: cuerpo.MessageSid || null,
      agencia: leerEnv('AGENCY_NAME', 'la inmobiliaria'),
      // Proveedor del LLM de clasificación: gemini (default, tiene free tier),
      // anthropic o groq. El modelo y la URL son opcionales — si no se
      // configuran, "Build LLM Request" usa el default de cada proveedor.
      proveedorLlm: leerEnv('LLM_PROVIDER', 'gemini').toLowerCase(),
      modelo: leerEnv('LLM_MODEL', ''),
      apiUrlLlm: leerEnv('LLM_API_URL', '') || null,
      recibidoEn: new Date().toISOString(),
    },
  },
];

