const item = $input.first().json;

const { url, headers, body } = buildLlmRequest({
  proveedor: item.proveedorLlm,
  modelo: item.modelo || undefined,
  apiUrl: item.apiUrlLlm || undefined,
  promptSistema: item.promptSistema,
  mensajeUsuario: item.mensajeUsuario,
});

// "Specify Headers > JSON" y el body del HTTP Request node necesitan un
// string JSON, no un objeto: si se les pasa un objeto por expresión, n8n lo
// castea con String() antes de intentar parsearlo como JSON y el resultado
// es el literal "[object Object]", que falla con "JSON parameter needs to
// be valid JSON". Por eso se stringifica acá, no en buildLlmRequest (que
// devuelve objetos para que sea fácil de testear).
return [
  {
    json: {
      ...item,
      llmUrl: url,
      llmHeaders: JSON.stringify(headers),
      llmBody: JSON.stringify(body),
    },
  },
];

